head.script:
scwin.gVar = {
    "cAnimationColor" : "",
    "cAnimationType" : "",
    "cClass" : "",
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {    
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        animationColor : scwin.gVar["cAnimationColor"],
        animationType : scwin.gVar["cAnimationType"],
        type : "anchor",
        class : scwin.gVar["cClass"],
        style : "width:150px; height:50px;",
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createEmptyTrigger(cList);
}
